import{_ as t,o as e,c as r,a2 as a}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"插件管理","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/plugins.md","filePath":"zh-CN/user-guide/settings/plugins.md","lastUpdated":1788579143000}'),n={name:"zh-CN/user-guide/settings/plugins.md"};function l(s,o,i,d,g,c){return e(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="插件管理" tabindex="-1">插件管理 <a class="header-anchor" href="#插件管理" aria-label="Permalink to &quot;插件管理&quot;">​</a></h1><p>Lertaro 拥有高度模块化的插件化架构体系。无论是核心扩展组件、本地工具还是社区第三方生态，均可在插件管理中心中统一查看、管理与配置。页面路径为<strong>设置 → 插件</strong>。</p><h2 id="_1-页面布局与-sdk-版本" tabindex="-1">1. 页面布局与 SDK 版本 <a class="header-anchor" href="#_1-页面布局与-sdk-版本" aria-label="Permalink to &quot;1. 页面布局与 SDK 版本&quot;">​</a></h2><ul><li><strong>Plugin SDK 徽标</strong>：页面顶部右上角醒目标注了当前运行时加载的 <code>Lertaro.PluginSdk</code> 版本号。点击该徽标可直接跳转至<a href="./../../dev-guide/"><strong>开发者手册</strong></a>查阅接口文档。</li><li><strong>左右双栏独立滚动</strong>：左侧展示已安装的所有插件列表，右侧展示当前选中插件的详细信息与配置面板，两侧独立滚动互不干扰。</li></ul><h2 id="_2-插件详情与组件开关" tabindex="-1">2. 插件详情与组件开关 <a class="header-anchor" href="#_2-插件详情与组件开关" aria-label="Permalink to &quot;2. 插件详情与组件开关&quot;">​</a></h2><p>点击左侧列表中的任意插件后，右侧会展示该插件的图标、名称、版本号与功能简介：</p><h3 id="详情标签页-details" tabindex="-1">详情标签页（Details） <a class="header-anchor" href="#详情标签页-details" aria-label="Permalink to &quot;详情标签页（Details）&quot;">​</a></h3><ul><li><strong>组件清单与分组</strong>：清晰列出该插件注册的所有底层功能组件（例如：搜索源、右键动作、快速导航提供者、即时预览解析器等）。</li><li><strong>组件级独立开关</strong>：每个非必要组件均配有独立的<strong>启用/禁用复选框</strong>；带有锁形图标的组件为系统级必要核心，不可关闭。</li><li><strong>一键全选/全不选</strong>：当某个组件分组包含多个可切换项目时，标题右侧会提供便捷的“全选/全不选”链接。</li><li><strong>组件悬停说明</strong>：鼠标悬停在组件旁边的 <strong>(!)</strong> 图标上，可查看该组件的底层实现说明与触发方式。</li></ul><h3 id="配置标签页-configure" tabindex="-1">配置标签页（Configure） <a class="header-anchor" href="#配置标签页-configure" aria-label="Permalink to &quot;配置标签页（Configure）&quot;">​</a></h3><ul><li><strong>原生嵌入式表单</strong>：插件自定义的配置项会直接渲染在右侧面板中，无需弹出额外的杂乱对话框。支持文本框、数字调节、开关、下拉选择及多分组子标签页。</li><li><strong>图标输入字段</strong>：使用 Schema 键 <code>Icon</code> 的文本框会显示图标预览，并支持 WPF Path Data。粘贴完整 SVG/XML 文档时会自动提取并合并其中的路径数据；无效的图标内容会被清空，并通过主题化对话框提示。</li><li><strong>安全提交与回滚机制</strong>：在右下角点击<strong>确定</strong>之前，任何修改均仅暂存于内存中；若直接切换至其他插件或离开页面，未保存的修改会自动安全回滚至原始状态，防止误提交。</li></ul><h2 id="_3-flow-launcher-社区生态深度支持" tabindex="-1">3. Flow Launcher 社区生态深度支持 <a class="header-anchor" href="#_3-flow-launcher-社区生态深度支持" aria-label="Permalink to &quot;3. Flow Launcher 社区生态深度支持&quot;">​</a></h2><p>除了基于 <code>Lertaro.PluginSdk</code> 构建的原生 C# 插件之外，Lertaro 还通过内置的 <strong>Flow Launcher Bridge</strong> 提供了对庞大 Flow Launcher 社区插件生态的原生级兼容支持。</p><h3 id="多语言运行时与隔离环境" tabindex="-1">多语言运行时与隔离环境 <a class="header-anchor" href="#多语言运行时与隔离环境" aria-label="Permalink to &quot;多语言运行时与隔离环境&quot;">​</a></h3><ul><li><strong>全类型插件兼容</strong>：无缝运行由 <strong>C# (.NET)</strong>、<strong>Python 3.12</strong>、<strong>Node.js v20 LTS</strong> 以及独立可执行程序（<code>.exe</code>）编写的 Flow Launcher 插件。</li><li><strong>零依赖污染与自包含运行时</strong>：Python（<code>FlowData\\PythonEmbeded-{arch}</code>）与 Node.js（<code>FlowData\\NodeEmbeded-{arch}</code>）运行时完全隔离在 Lertaro 的用户数据目录中按需自动下载部署，不依赖且绝不污染 Windows 系统的全局环境变量与 PATH。</li><li><strong>依赖自动安装</strong>：插件首次加载时，系统会在后台静默根据 <code>requirements.txt</code> 安装 Python <code>pip</code> 依赖，或根据 <code>package.json</code> 执行 <code>npm</code> 依赖安装。</li></ul><h3 id="在线社区市场与包管理指令" tabindex="-1">在线社区市场与包管理指令 <a class="header-anchor" href="#在线社区市场与包管理指令" aria-label="Permalink to &quot;在线社区市场与包管理指令&quot;">​</a></h3><p>你可以直接在 Lertaro 搜索框中键入以下指令管理 Flow 插件：</p><ul><li><strong><code>flow install &lt;关键词&gt;</code></strong>：实时在线检索 Flow.Launcher 官方社区插件库，选中后一键自动下载、解压、部署并拉起依赖安装。</li><li><strong><code>flow update</code></strong>：自动检测所有已安装 Flow 插件的更新版本并支持一键升级。</li><li><strong><code>flow uninstall &lt;插件名&gt;</code></strong>：一键安全卸载指定的 Flow 插件并清理相关本地目录。</li><li><strong>手动安装</strong>：亦可将下载好的第三方 Flow 插件文件夹直接放入 <code>&lt;用户数据目录&gt;\\FlowData\\Plugins\\</code> 完成本地离线安装。</li></ul><h3 id="插件配置、触发词与交互式预览" tabindex="-1">插件配置、触发词与交互式预览 <a class="header-anchor" href="#插件配置、触发词与交互式预览" aria-label="Permalink to &quot;插件配置、触发词与交互式预览&quot;">​</a></h3><ul><li><strong>集中管理与触发词修改</strong>：在<strong>设置 → 插件 → Flow Launcher Bridge → 配置</strong>中，可为每个 Flow 插件单独开关，并自由修改其专属<strong>触发词（ActionKeyword）</strong>。配置集中持久化在 <code>FlowData\\Settings\\Plugins.json</code> 中，插件更新后配置不丢失。</li><li><strong>动态配置表单</strong>：完整支持 Flow 插件基于 YAML/JSON 模板表单（<code>SettingsTemplate.yaml</code>/<code>.json</code>）或 C# WPF 设置面板（<code>ISettingProvider</code>）的配置界面，自动融合当前深浅色主题并支持 i18n 本地化。</li><li><strong>WebView2 交互式富文本预览</strong>：支持 Flow 插件返回的复杂预览面板（如 MDict 词典释义、天气卡片、API 调试信息、网页快照等），在 QuickLook 中免额外按键平滑展开；Lertaro 会自动注入深浅色自适应样式、清晰字体与精致滚动条。</li><li><strong>宿主能力深度融合</strong>：Flow 插件通过 API 打开文件夹时自动遵循宿主配置的第三方文件管理器，弹窗消息框自动渲染为宿主主题自绘样式，且内部日志无缝汇入设置中心日志查看器。</li><li><strong>快捷总览</strong>：在搜索框中直接输入 <code>flow</code> 即可列出当前已加载的所有 Flow 插件及其触发词；选中插件后会直接跳转到设置中的对应配置分组。</li></ul><h2 id="_4-音频设备选择器" tabindex="-1">4. 音频设备选择器 <a class="header-anchor" href="#_4-音频设备选择器" aria-label="Permalink to &quot;4. 音频设备选择器&quot;">​</a></h2><p><strong>音频设备选择器</strong>是一个仅支持 Windows 的原生插件。输入 <code>ad</code> 可列出当前活动的播放和输入设备，选择设备后会将其设为对应的默认多媒体设备；也可以在触发词后附加设备名称来筛选结果。</p><p>插件设置支持修改触发词，并选择结果显示友好名称、设备名称或设备描述。它可以切换默认播放或输入端点，但不负责音量、静音或单应用音频路由。</p><h2 id="_5-内容搜索" tabindex="-1">5. 内容搜索 <a class="header-anchor" href="#_5-内容搜索" aria-label="Permalink to &quot;5. 内容搜索&quot;">​</a></h2><p><strong>内容搜索</strong>插件可以搜索配置的本地文档正文。打开它的<strong>配置</strong>标签页，可以设置触发关键字、监测文件夹、索引后缀、单个文件大小上限、索引体积上限以及排除完整路径的正则表达式。默认触发关键字为 <code>cs</code>，因此输入 <code>cs 项目计划</code> 即可搜索文档正文，并显示带片段的匹配文件。</p><p>配置中还提供<strong>清空索引</strong>与<strong>重建索引</strong>。清空索引只删除内容索引，重建索引则会删除内容索引并重新扫描所有监测文件夹。这两个操作都不会删除 Lertaro 的普通文件名索引。</p><h2 id="_6-插件运行状态" tabindex="-1">6. 插件运行状态 <a class="header-anchor" href="#_6-插件运行状态" aria-label="Permalink to &quot;6. 插件运行状态&quot;">​</a></h2><p>在<strong>设置 → 插件 → 运行状态</strong>中，可以查看 Lertaro 运行期间已安装插件的宿主侧调用情况。数据按插件汇总，并在该标签页打开时持续刷新。</p><ul><li><strong>插件筛选</strong>：使用筛选框按插件名称进行模糊搜索。</li><li><strong>列排序</strong>：点击列头可依次切换升序、降序和默认插件顺序。</li><li><strong>可用指标</strong>：调用次数、平均耗时、最近耗时、最大耗时、托管分配量和观测到的异常次数。</li><li><strong>统计范围</strong>：统计在当前 Lertaro 进程运行期间累计，重启后重置。数值为零表示尚未记录到对应的调用；托管分配量是被测调用产生的托管内存分配，不代表插件的全部私有内存占用。</li></ul>',28)])])}const p=t(n,[["render",l]]);export{u as __pageData,p as default};
